func buildSeatingData01Sep2026FNto02Sep2026AN() []models.SeatingRecord {
	var allRecords []models.SeatingRecord
	allRecords = append(allRecords, buildSeatingData31Aug2026FN()...)
	allRecords = append(allRecords, buildSeatingData31Aug2026AN()...)
	allRecords = append(allRecords, buildSeatingData01Sep2026FN()...)
	allRecords = append(allRecords, buildSeatingData01Sep2026AN()...)
	allRecords = append(allRecords, buildSeatingData02Sep2026FN()...)
	allRecords = append(allRecords, buildSeatingData02Sep2026AN()...)
	allRecords = append(allRecords, buildSeatingData03Sep2026FN()...)
	allRecords = append(allRecords, buildSeatingData03Sep2026AN()...)
	allRecords = append(allRecords, buildSeatingData03Sep2026FNElectives()...)
	allRecords = append(allRecords, buildSeatingData05Sep2026FN()...)
	allRecords = append(allRecords, buildSeatingData01Sep2026FN_Sem5()...)
	allRecords = append(allRecords, buildSeatingData01Sep2026AN_Sem5()...)
	allRecords = append(allRecords, buildSeatingData02Sep2026FN_Sem5()...)
	allRecords = append(allRecords, buildSeatingData02Sep2026AN_Sem5()...)
	return allRecords
}
// LookupHall returns the hall number for a given register number and course code.
func LookupHall(registerNo, courseCode string) (string, bool) {
	registerNo = strings.TrimSpace(strings.ToUpper(registerNo))
	courseCode = strings.TrimSpace(strings.ToUpper(courseCode))

	allRecords := buildSeatingData01Sep2026FNto02Sep2026AN()

	for _, record := range allRecords {
		if strings.ToUpper(record.CourseCode) != courseCode {
			continue
		}

		for _, reg := range record.RegisterNos {
			if strings.ToUpper(reg) == registerNo {
				return record.HallNo, true
			}
		}
	}

	return "", false
}

